def check_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    try:
        numerator = (x + 1)**y
        denominator = x**z + 1

        # Check if the division results in a positive integer
        if denominator != 0 and numerator % denominator == 0:
            return True, numerator // denominator
        else:
            return False, None
    except OverflowError:
        # Should not happen with x,y,z <= 5, but good practice
        return False, None

results = []
for x in range(1, 6):
