def is_good_triple(x, y, z):
    # Check if x^z + 1 divides (x+1)^y
    divisor = x**z + 1
    dividend = (x + 1)**y

    # Since x, y, z are positive integers, both are positive, so we just check divisibility.
    if dividend % divisor == 0:
        return True
    return False

